    private final ThirdPartyWaypointManager thirdPartyWaypointManager;
    protected XaeroPath path;

    protected MinimapWorldContainer(HudMod modMain, MinimapSession session, XaeroPath path, MinimapWorldRootContainer rootContainer) {
        if (path.getLastNode().contains(":")) {
            throw new IllegalArgumentException();
        }
        this.modMain = modMain;
        this.session = session;
        this.path = path;
        this.rootContainer = rootContainer;
        this.worlds = new HashMap<String, MinimapWorld>();
        this.subContainers = new HashMap<String, MinimapWorldContainer>();
        this.worldNames = new HashMap<String, String>();
        this.equivalentDimId = this.determineDimensionEquivalent();
        this.thirdPartyWaypointManager = path.getNodeCount() != 2 ? null : new ThirdPartyWaypointManager(session);
        this.serverWaypointManager = new ServerWaypointManager(this.thirdPartyWaypointManager);
    }

    private ResourceKey<Level> determineDimensionEquivalent() {
        ResourceKey<Level> dimKey;
        if (this.path.getNodeCount() < 2) {
            return null;
        }
        String secondNode = this.path.getAtIndex(1).getLastNode();
        if (secondNode.startsWith("dim%") && (dimKey = this.session.getDimensionHelper().getDimensionKeyForDirectoryName(secondNode)) != null) {
            return dimKey;
        }
        return null;
    }

